function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W / 2, H / 2 - 100, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // cucumber
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.rect(W / 2 - 25, H / 2, 50, 100);
  ctx.fill();
  ctx.stroke();

  // water droplets
  ctx.fillStyle = 'blue';
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(W / 2 - 25 + i * 10, H / 2 - 50 + Math.sin(t + i) * 20, 5, 0, 2 * Math.PI);
    ctx.fill();
  }

  // stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W / 2 + 100, H / 2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 + 100, H / 2 + 20);
  ctx.lineTo(W / 2 + 100, H / 2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 + 100, H / 2 + 50);
  ctx.lineTo(W / 2 + 80, H / 2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 + 100, H / 2 + 50);
  ctx.lineTo(W / 2 + 120, H / 2 + 70);
  ctx.stroke();

  ctx.restore();
}
